import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const s = input[0];

let x = 0;
let y = 0;
for (const c of s) {
  if (c === "U") y++;
  else if (c === "D") y--;
  else if (c === "R") x++;
  else x--;
}
console.log(x + " " + y + " " + (Math.abs(x) + Math.abs(y)));
